import{_ as l,W as t,X as i,a0 as o}from"./framework-5f3abea5.js";const r={},s=o("<p>Spring 为开发者提供了丰富多样的工具类，这些工具类涵盖了从 Bean 操作、集合处理、字符串处理，到反射操作、文件复制、资源加载等几乎所有开发场景，它可以大幅提升开发效率和代码质量。不废话，直接上干货！</p><p><strong>1. BeanUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.beans.BeanUtils</li><li><strong>用途</strong>：提供操作JavaBean属性的便利方法，常用于复制同名属性从一个bean到另一个bean。</li><li><strong>主要方法</strong>： <ul><li><code>copyProperties(Object source, Object target)</code>：从源对象复制属性到目标对象，忽略不同数据类型的属性。</li><li><code>instantiateClass(Class&lt;T&gt; clazz)</code>：使用其无参构造器实例化一个类。</li></ul></li></ul><p><strong>2. CollectionUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.CollectionUtils</li><li><strong>用途</strong>：提供各种集合操作的工具方法。</li><li><strong>主要方法</strong>： <ul><li><code>isEmpty(Collection&lt;?&gt; collection)</code>：检查集合是否为空或null。</li><li><code>mergeArrayIntoCollection(Object array, Collection&lt;Object&gt; collection)</code>：将数组中的元素合并到集合中。</li><li><code>findValueOfType(Collection&lt;?&gt; collection, Class&lt;?&gt; type)</code>：在集合中查找指定类型的元素。</li></ul></li></ul><p><strong>3. StringUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.StringUtils</li><li><strong>用途</strong>：提供各种字符串处理的工具方法。</li><li><strong>主要方法</strong>： <ul><li>hasText(String str)：检查字符串是否包含非空白字符。</li><li>commaDelimitedListToStringArray(String str)：将逗号分隔的字符串转换为字符串数组。</li><li>split(String toSplit, String delimiter)：分割字符串但不使用正则表达式。</li></ul></li></ul><p><strong>4. ObjectUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.ObjectUtils</li><li><strong>用途</strong>：提供各种对象操作的工具方法。</li><li><strong>主要方法</strong>： <ul><li>isEmpty(Object obj)：检查对象、数组是否为空或null。</li><li>nullSafeEquals(Object o1, Object o2)：null安全的比较两个对象是否相等。</li></ul></li></ul><p><strong>5. ReflectionUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.ReflectionUtils</li><li><strong>用途</strong>：提供反射相关的工具方法，简化对Java反射API的使用。</li><li><strong>主要方法</strong>： <ul><li><code>doWithFields(Class&lt;?&gt; clazz, ReflectionUtils.FieldCallback fc)</code>：对指定类的每个字段执行给定的回调。</li><li><code>findMethod(Class&lt;?&gt; clazz, String name, Class&lt;?&gt;... paramTypes)</code>：在指定类中查找方法。</li></ul></li></ul><p><strong>6. ClassUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.ClassUtils</li><li><strong>用途</strong>：提供与类和类加载器相关的工具方法。</li><li><strong>主要方法</strong>： <ul><li>getDefaultClassLoader()：获取默认类加载器。</li><li>isPresent(String className, ClassLoader classLoader)：检查给定名称的类是否存在。</li></ul></li></ul><p><strong>7. AopUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.aop.support.AopUtils</li><li><strong>用途</strong>：提供与面向切面编程相关的工具方法。</li><li><strong>主要方法</strong>： <ul><li>isAopProxy(Object obj)：检查给定对象是否为AOP代理。</li><li>getTargetClass(Object candidate)：获取代理对象背后的目标类。</li></ul></li></ul><p><strong>8. PropertyAccessorUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.beans.PropertyAccessorUtils</li><li><strong>用途</strong>：提供属性访问器相关的工具方法。</li><li><strong>主要方法</strong>： <ul><li>getPropertyAccessorName(String propertyName)：从复合属性名中获取最终的属性访问器名。</li></ul></li></ul><p><strong>9. FileCopyUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.FileCopyUtils</li><li><strong>用途</strong>：提供文件复制相关的工具方法。</li><li><strong>主要方法</strong>： <ul><li><code>copy(byte[] in, OutputStream out)</code>：将字节数组复制到输出流。</li><li><code>copy(File in, File out)</code>：将一个文件内容复制到另一个文件。</li></ul></li></ul><p><strong>10. ResourceUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.util.ResourceUtils</li><li><strong>用途</strong>：识别资源加载的工具类，帮助加载类路径或者文件系统内的资源文件。</li><li><strong>主要方法</strong>： <ul><li>getFile(String resourceLocation)：根据资源路径获取文件。</li><li>getURL(String resourceLocation)：根据资源路径获取URL。</li></ul></li></ul><p><strong>11. TransactionSynchronizationManager</strong></p><ul><li><strong>类路径</strong>：org.springframework.transaction.support.TransactionSynchronizationManager</li><li><strong>用途</strong>：用于事务同步，管理资源和事务同步相关的回调。</li><li><strong>主要方法</strong>： <ul><li><code>bindResource(Object key, Object value)</code>：绑定资源到当前事务。</li><li><code>getResource(Object key)</code>：获取绑定到当前事务的资源。</li></ul></li></ul><p><strong>12. WebUtils</strong></p><ul><li><strong>类路径</strong>：org.springframework.web.util.WebUtils</li><li><strong>用途</strong>：为Web应用程序提供工具方法。</li><li><strong>主要方法</strong>： <ul><li><code>getRealPath(ServletContext servletContext, String path)</code>：获取相对于Web应用根目录的真实路径。</li><li><code>findParameterValue(Map&lt;String, ?&gt; params, String paramName)</code>：在参数Map中查找指定的参数值。</li></ul></li></ul><p><strong>13. Instant 统计时间的类</strong></p><ul><li><strong>类路径</strong>：java.time.Instant</li><li><strong>用途</strong>：用于时间的统计与处理，可精确到纳秒，支持时间戳的获取、时间点的比较和计算等操作，常用于记录事件发生时间、统计程序执行耗时等场景。</li><li><strong>主要方法</strong>： <ul><li>now()：获取当前的时间点（UTC 时间）。</li><li>toEpochMilli()：将当前时间点转换为从 1970-01-01 00:00:00 UTC 开始计算的毫秒数时间戳。</li><li>isAfter(Instant otherInstant)：判断当前时间点是否在另一个时间点之后。</li></ul></li></ul>",27),n=[s];function e(g,a){return t(),i("div",null,n)}const u=l(r,[["render",e],["__file","Spring中的各种工具类.html.vue"]]);export{u as default};
